-- =============================================================================
-- align_metrologia_certificado_nhojas.sql · Certificado de calibración de N hojas
-- -----------------------------------------------------------------------------
-- Respuesta del Laboratorio de Metrología del 21-10-2026 a la maqueta (12
-- observaciones) · reglas en docs/FLUJO_METROLOGIA.md §8 (frente r1e).
--
--   1. met_calibracion.presentacion (JSONB): lo que el metrólogo decide sobre el
--      documento y no sobre el cálculo: acreditación por certificado (con logo o
--      sin él, con motivo), «reemplaza al certificado N°» a mano (con motivo),
--      observaciones editables, condiciones propias de la IT y modo del esquema.
--   2. met_calibracion.esquema_*: esquema o imagen propia de la calibración
--      (por ejemplo, la posición de los sensores en un isotermo).
--   3. met_imagen: imágenes de configuración de Metrología: el logo de
--      acreditación (lo carga el IDIC) y el esquema por defecto de cada proceso.
--      Se siembra el esquema estándar de ITT02 (libro LMT-PG01-P01-ITT02 y caso
--      T-2890, «Representación esquemática de la posición de los sensores»).
--   4. Bitácora: acción CERTIFICADO (cambio de la presentación del certificado).
--
-- Aditivo e idempotente: una pasada deja la misma base que dos. Va al FINAL de
-- ORDEN_SQL.txt. Sin permisos nuevos (metrologia.ver, metrologia.crear,
-- metrologia.config).
-- =============================================================================

-- --- 1 y 2 · Presentación y esquema de la calibración -------------------------
ALTER TABLE met_calibracion ADD COLUMN IF NOT EXISTS presentacion   JSONB        NOT NULL DEFAULT '{}';
ALTER TABLE met_calibracion ADD COLUMN IF NOT EXISTS esquema_mime   VARCHAR(20)  CHECK (esquema_mime IS NULL OR esquema_mime IN ('image/png', 'image/jpeg'));
ALTER TABLE met_calibracion ADD COLUMN IF NOT EXISTS esquema_datos  TEXT;          -- base64 (sin prefijo data:)
ALTER TABLE met_calibracion ADD COLUMN IF NOT EXISTS esquema_hash   VARCHAR(64);
ALTER TABLE met_calibracion ADD COLUMN IF NOT EXISTS esquema_nombre VARCHAR(200);

-- --- 3 · Imágenes de configuración ----------------------------------------------
CREATE TABLE IF NOT EXISTS met_imagen (
  tenant_id       UUID         NOT NULL REFERENCES tenant(id),
  clave           VARCHAR(40)  NOT NULL CHECK (clave ~ '^(logo_acreditacion|esquema:[A-Za-z0-9-]{2,20})$'),
  titulo          VARCHAR(200),
  mime            VARCHAR(20)  NOT NULL CHECK (mime IN ('image/png', 'image/jpeg')),
  bytes           INTEGER      NOT NULL CHECK (bytes > 0),
  datos           TEXT         NOT NULL,   -- base64 (sin prefijo data:)
  hash_sha256     VARCHAR(64)  NOT NULL,
  nombre          VARCHAR(200),
  actualizado_por UUID         REFERENCES usuario(id),
  updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, clave)
);

-- Esquema estándar de ITT02 (medios isotermos): imagen del libro de trabajo del LMT.
INSERT INTO met_imagen (tenant_id, clave, titulo, mime, bytes, datos, hash_sha256, nombre)
SELECT t.id, 'esquema:ITT02', 'Representación esquemática de la posición de los sensores', 'image/png',
       length(decode(e.b64, 'base64')), e.b64, encode(sha256(decode(e.b64, 'base64')), 'hex'), 'LMT-PG01-P01-ITT02 (T-2890).png'
  FROM tenant t
 CROSS JOIN (SELECT ''::text AS b64) e
ON CONFLICT (tenant_id, clave) DO NOTHING;

-- --- 4 · Bitácora ----------------------------------------------------------------
ALTER TABLE met_calibracion_evento DROP CONSTRAINT IF EXISTS met_calibracion_evento_accion_check;
ALTER TABLE met_calibracion_evento ADD CONSTRAINT met_calibracion_evento_accion_check
  CHECK (accion IN ('CREADA', 'EDITADA', 'ENVIADA', 'DEVUELTA', 'FIRMADA', 'EMITIDA', 'REEMISION', 'REEMPLAZADA', 'ENTREGADA', 'CERTIFICADO'));
